CREATE COLUMN TABLE "TEST_AP"."ARSB" ("ResGrpCod" SMALLINT CS_INT NOT NULL , "ResGrpNam" NVARCHAR(20) NOT NULL , "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Object" NVARCHAR(20) DEFAULT '292', "logInstanc" INTEGER CS_INT NOT NULL , "createDate" LONGDATE CS_LONGDATE, "userSign2" SMALLINT CS_INT, "updateDate" LONGDATE CS_LONGDATE, "ResType" NVARCHAR(1) DEFAULT 'M', "CostName1" NVARCHAR(254), "CostVal1" DECIMAL(21,6) CS_FIXED, "CostName2" NVARCHAR(254), "CostVal2" DECIMAL(21,6) CS_FIXED, "CostName3" NVARCHAR(254), "CostVal3" DECIMAL(21,6) CS_FIXED, "CostName4" NVARCHAR(254), "CostVal4" DECIMAL(21,6) CS_FIXED, "CostName5" NVARCHAR(254), "CostVal5" DECIMAL(21,6) CS_FIXED, "CostName6" NVARCHAR(254), "CostVal6" DECIMAL(21,6) CS_FIXED, "CostName7" NVARCHAR(254), "CostVal7" DECIMAL(21,6) CS_FIXED, "CostName8" NVARCHAR(254), "CostVal8" DECIMAL(21,6) CS_FIXED, "CostName9" NVARCHAR(254), "CostVal9" DECIMAL(21,6) CS_FIXED, "CostName10" NVARCHAR(254), "CostVal10" DECIMAL(21,6) CS_FIXED, "ResUoM" NVARCHAR(20), PRIMARY KEY ("ResGrpCod", "logInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
